import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs/promises';
import * as os from 'node:os';
import * as path from 'node:path';
import { FileDiscoveryService } from './fileDiscoveryService.js';
import { getNormalizedRelativePath } from '../utils/ignorePathUtils.js';
import { GEMINI_IGNORE_FILE_NAME } from '../config/constants.js';

describe('scratch new features', () => {
  let projectRoot: string;
  async function write(p: string, c = '') {
    const full = path.join(projectRoot, p);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, c);
  }
  beforeEach(async () => {
    projectRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'scratch-'));
  });
  afterEach(async () => {
    await fs.rm(projectRoot, { recursive: true, force: true });
  });

  it('getNormalizedRelativePath basics', () => {
    const r = '/proj';
    expect(getNormalizedRelativePath(r, '', false)).toBe(null);
    expect(getNormalizedRelativePath(r, null as unknown as string, false)).toBe(
      null,
    );
    expect(getNormalizedRelativePath(r, '../outside/f', false)).toBe(null);
    expect(getNormalizedRelativePath(r, '/proj-sibling/f', false)).toBe(null);
    expect(getNormalizedRelativePath(r, r, true)).toBe('/');
    expect(getNormalizedRelativePath(r, r, false)).toBe('');
    expect(getNormalizedRelativePath(r, '/proj/src/a', true)).toBe('src/a/');
    expect(getNormalizedRelativePath(r, '/proj/src/a/', false)).toBe('src/a');
    expect(getNormalizedRelativePath('C:\\proj', 'D:\\other', false)).toBe(
      null,
    );
  });

  it('getIgnoredPaths gemini only vs git only', async () => {
    await fs.mkdir(path.join(projectRoot, '.git'), { recursive: true });
    await write('.gitignore', 'gitdir/\n');
    await write(GEMINI_IGNORE_FILE_NAME, 'geminidir/\n');
    await write('gitdir/a.txt', 'x');
    await write('geminidir/b.txt', 'x');
    await write('src/keep.ts', 'x');

    const svc = new FileDiscoveryService(projectRoot);

    const geminiOnly = await svc.getIgnoredPaths({
      respectGitIgnore: false,
      respectGeminiIgnore: true,
    });
    expect(geminiOnly).toContain(path.join(projectRoot, 'geminidir'));
    expect(geminiOnly).not.toContain(path.join(projectRoot, 'gitdir'));

    const gitOnly = await svc.getIgnoredPaths({
      respectGitIgnore: true,
      respectGeminiIgnore: false,
    });
    expect(gitOnly).toContain(path.join(projectRoot, 'gitdir'));
    expect(gitOnly).toContain(path.join(projectRoot, '.git'));
    expect(gitOnly).not.toContain(path.join(projectRoot, 'geminidir'));

    // ignored dir not traversed
    expect(gitOnly).not.toContain(path.join(projectRoot, 'gitdir', 'a.txt'));
    // shouldIgnoreDirectory
    expect(
      svc.shouldIgnoreDirectory(path.join(projectRoot, 'gitdir')),
    ).toBe(true);
    expect(svc.shouldIgnoreDirectory(path.join(projectRoot, 'src'))).toBe(
      false,
    );
  });

  it('respects un-ignore patterns', async () => {
    await fs.mkdir(path.join(projectRoot, '.git'), { recursive: true });
    await write('.gitignore', 'logs/\n');
    await write(GEMINI_IGNORE_FILE_NAME, '!logs/\n');
    await write('logs/app.log', 'x');
    const svc = new FileDiscoveryService(projectRoot);
    const all = await svc.getIgnoredPaths();
    expect(all).not.toContain(path.join(projectRoot, 'logs'));
  });
});
